//! The design tokens as Rust constants.
//!
//! Generated by `cargo xtask codegen` from `resources/style/tokens.json`. Do not
//! edit: change the JSON and run the command again. `tokens.css` holds the same
//! colours for the stylesheet.

#![allow(dead_code)]

use super::color::Rgba;

